#!/usr/bin/env node
// Renders every scenario of every mockup board (.dc.html) to a PNG at 240 x 320, 1x, with a small
// stand-in for the design runtime: it evaluates the board's renderVals() for each scenario and expands
// {{ holes }}, <sc-if> and <sc-for>. Boards generated by gen.py (canvas/project) replace the published
// copies in boards/ of the same name.
//
// Usage: node render_boards.js --fonts DIR --out DIR [--gen DIR] [Board ...]
//   --fonts  folder holding @fontsource/barlow and @fontsource/barlow-condensed (node_modules/@fontsource)
//   --gen    gen.py output folder (canvas/project); default ./canvas/project
// Prints Board:scenario for each PNG. Not a test: the published artifact stays the source of truth.
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const args = process.argv.slice(2);
const opt = { fonts: null, out: null, gen: path.join(__dirname, 'canvas', 'project'), only: [] };
for (let i = 0; i < args.length; i++) {
  if (args[i] === '--fonts') opt.fonts = args[++i];
  else if (args[i] === '--out') opt.out = args[++i];
  else if (args[i] === '--gen') opt.gen = args[++i];
  else opt.only.push(args[i]);
}
if (!opt.fonts || !opt.out) { console.error('usage: render_boards.js --fonts DIR --out DIR [--gen DIR] [Board...]'); process.exit(2); }
fs.mkdirSync(opt.out, { recursive: true });

const ORDER = JSON.parse(fs.readFileSync(path.join(__dirname, 'boards', 'canvas.json'), 'utf8')).order;

function source(file) {
  const g = path.join(opt.gen, file);
  if (fs.existsSync(g)) return { html: fs.readFileSync(g, 'utf8'), from: 'gen.py' };
  return { html: fs.readFileSync(path.join(__dirname, 'boards', file), 'utf8'), from: 'artifact' };
}

function lookup(vals, expr) {
  expr = expr.trim();
  let v = vals;
  for (const k of expr.split('.')) { if (v == null) return ''; v = v[k]; }
  return v;
}

function expand(tpl, vals) {
  // <sc-for list="{{ x }}" as="y" ...>inner</sc-for>
  tpl = tpl.replace(/<sc-for\s+list="\{\{\s*([\w.]+)\s*\}\}"\s+as="(\w+)"[^>]*>([\s\S]*?)<\/sc-for>/g,
    (m, list, as, inner) => (lookup(vals, list) || []).map(item => expand(inner, Object.assign({}, vals, { [as]: item }))).join(''));
  // <sc-if value="{{ x }}" ...>inner</sc-if>
  tpl = tpl.replace(/<sc-if\s+value="\{\{\s*([\w.]+)\s*\}\}"[^>]*>([\s\S]*?)<\/sc-if>/g,
    (m, cond, inner) => (lookup(vals, cond) ? expand(inner, vals) : ''));
  return tpl.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (m, e) => String(lookup(vals, e)));
}

function scenarios(html) {
  const m = html.match(/data-props='([^']*)'/);
  const props = m ? JSON.parse(m[1]) : {};
  const s = props.scenario;
  return s && s.options ? s.options : ['only'];
}

function renderVals(html, scenario) {
  const m = html.match(/<script type="text\/x-dc"[^>]*>([\s\S]*?)<\/script>/);
  const code = m ? m[1] : 'class Component extends DCLogic { renderVals() { return {}; } }';
  // eslint-disable-next-line no-new-func
  const C = new Function('DCLogic', code + '\nreturn Component;')(class { constructor(p) { this.props = p; } });
  return new C({ scenario: scenario === 'only' ? undefined : scenario }).renderVals();
}

function fontFaces() {
  const out = [];
  for (const [fam, folder] of [['Barlow', 'barlow'], ['Barlow Condensed', 'barlow-condensed']])
    for (const w of [500, 600, 700])
      out.push(`@font-face{font-family:'${fam}';font-weight:${w};src:url('file://${path.resolve(opt.fonts)}/${folder}/files/${folder}-latin-${w}-normal.woff2') format('woff2')}`);
  return out.join('\n');
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 240, height: 320 }, deviceScaleFactor: 1 });
  const index = [];
  for (const file of ORDER) {
    const board = file.replace('.dc.html', '');
    if (opt.only.length && !opt.only.includes(board)) continue;
    const { html, from } = source(file);
    const body = html.match(/<x-dc>([\s\S]*)<\/x-dc>/)[1].replace(/<helmet>[\s\S]*?<\/helmet>/, '');
    for (const sc of scenarios(html)) {
      const content = expand(body, renderVals(html, sc));
      const doc = `<!doctype html><html><head><meta charset="utf-8"><style>${fontFaces()}\nbody{margin:0;background:#000}</style></head><body>${content}</body></html>`;
      const tmp = path.join(opt.out, `${board}__${sc}.html`);
      fs.writeFileSync(tmp, doc);
      await page.goto('file://' + path.resolve(tmp));
      await page.evaluate(() => document.fonts.ready);
      await page.waitForTimeout(50);
      const png = path.join(opt.out, `${board}__${sc}.png`);
      await page.screenshot({ path: png, clip: { x: 0, y: 0, width: 240, height: 320 } });
      fs.unlinkSync(tmp);
      index.push({ board, scenario: sc, png: path.basename(png), from });
      console.log(`${board}:${sc} (${from})`);
    }
  }
  fs.writeFileSync(path.join(opt.out, 'index.json'), JSON.stringify(index, null, 1));
  await browser.close();
})();
